        }
        (Some(value), None) => Ok(Some(value.to_string())),
        (None, Some(path)) => {
            let content = std::fs::read_to_string(path)?;
            Ok(Some(content.trim().to_string()))
        }
        (None, None) => Ok(None),
    }
}

