        llm_model_mid: args.llm_model_mid.clone(),
        llm_model_strong: args.llm_model_strong.clone(),
        llm_timeout_ms: args.llm_timeout_ms,
        llm_temperature: args.llm_temperature,
        llm_max_tokens: args.llm_max_tokens,
